function maximumInvitations(grid) {
  const boys = grid.length;
  const girls = grid[0].length;
  const partner = new Array(girls).fill(-1);
  let accepted = 0;

  for (let boy = 0; boy < boys; boy++) {
    const visited = new Array(girls).fill(false);
    if (tryInvite(boy, visited)) {
      accepted++;
    }
  }
  return accepted;

  function tryInvite(boy, visited) {
    for (let girl = 0; girl < girls; girl++) {
      if (grid[boy][girl] === 1 && !visited[girl]) {
        visited[girl] = true;
        if (partner[girl] === -1 || tryInvite(partner[girl], visited)) {
          partner[girl] = boy;
          return true;
        }
      }
    }
    return false;
  }
}

