function maximumInvitations(grid) {
  // Try every choice for every boy: skip him or give him a still-free allowed girl.
  const m = grid.length;
  const n = grid[0].length;
  const memo = new Map();
  const best = (i, used) => {
    if (i === m) return 0;
    const key = i * 4096 + used;
    if (memo.has(key)) return memo.get(key);
    let result = best(i + 1, used);
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1 && !(used & (1 << j))) result = Math.max(result, 1 + best(i + 1, used | (1 << j)));
    }
    memo.set(key, result);
    return result;
  };
  return best(0, 0);
}

