function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  // Sparse grids make the matching need many re-assignments; dense ones are easy.
  const density = size === 'large' ? [0.02, 0.04, 0.3][Math.floor(rand() * 3)] : rand();
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [grid];
}
